#!/usr/bin/env bash
# Builds the mods and copies them into a Prism instance (haven-create-hud is built into haven-create-ui-ux).
# resourcepacks/haven-create-hud is generated by tools/hudpack.py: change the pages, not the instance copy.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
instance="${1:-$HOME/.local/share/PrismLauncher/instances/Create Ultimate Selection 2/minecraft}"

for m in mod mobbars; do (cd "$here/$m" && JAVA_HOME="${JAVA_HOME:-/usr/lib/jvm/java-17-openjdk}" ./gradlew build -q --no-configuration-cache); done
rm -f "$instance"/mods/haven-create-ui-ux-*.jar "$instance"/mods/createdarkinventory-*.jar   # and the old name
rm -f "$instance"/mods/haven-mob-health-bars-*.jar
cp "$here"/mod/build/libs/haven-create-ui-ux-*.jar "$here"/mobbars/build/libs/haven-mob-health-bars-*.jar "$instance/mods/"
# Old packs: Create-HUD and the Veil fix became haven-create-hud, which is now built into haven-create-ui-ux.
rm -rf "$instance/resourcepacks/DarkModeEverywhere-Veil-Fix" "$instance/resourcepacks/Create-HUD" \
  "$instance/resourcepacks/haven-create-hud" "$instance/config/createdarkinventory-client.toml"
# Drop those packs from options.txt too (the built-in pack is not listed there).
if [ -f "$instance/options.txt" ]; then
  python3 -I - "$instance/options.txt" <<'PY'
import json, re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
old = {"file/haven-create-hud", "file/Create-HUD", "file/DarkModeEverywhere-Veil-Fix"}
for key in ("resourcePacks", "incompatibleResourcePacks"):
    m = re.search(rf"^{key}:(.*)$", s, re.M)
    if m:
        packs = [x for x in json.loads(m.group(1)) if x not in old]
        s = s[:m.start(1)] + json.dumps(packs, ensure_ascii=False, separators=(",", ":")) + s[m.end(1):]
open(p, "w", encoding="utf-8").write(s)
PY
fi
echo "Installed. Restart the game to load the mods."
